import{_ as a,o,c as t,a5 as c}from"./chunks/framework.CXvGqWf0.js";const m=JSON.parse('{"title":"漫画 · 第 57 话 布局计算与强制同步布局","description":"","frontmatter":{},"headers":[],"relativePath":"comics/mechanism/EP.57-forced-sync-layout.md","filePath":"comics/mechanism/EP.57-forced-sync-layout.md","lastUpdated":1793853676000}'),r={name:"comics/mechanism/EP.57-forced-sync-layout.md"};function i(l,e,n,d,s,h){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="漫画-·-第-57-话-布局计算与强制同步布局" tabindex="-1">漫画 · 第 57 话 布局计算与强制同步布局 <a class="header-anchor" href="#漫画-·-第-57-话-布局计算与强制同步布局" aria-label="Permalink to &quot;漫画 · 第 57 话 布局计算与强制同步布局&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/mechanism/03-layout-and-forced-sync">docs/mechanism/03-layout-and-forced-sync.md</a> ｜ 原画：<a href="./EP.57-forced-sync-layout.svg">EP.57-forced-sync-layout.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她写了个“等高卡片”循环，200 张卡片让页面卡了半秒。</li><li><strong>标签君</strong>：结构师。负责画出脏标记与强制布局的因果链，演示“全读全写”的改造。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱想把卡片拉成等高，循环里读一张 <code>offsetHeight</code> 就写一张 <code>minHeight</code>。结果每次循环都触发一次完整布局，200 次重排把主线程堵死。标签君把火焰图放大：Layout 事件层层叠叠，全是自己逼出来的。她改成“先读全部，再写全部”，布局次数从 200 降到 2。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>代码是 <code>el.style.minHeight = el.offsetHeight + &#39;px&#39;</code> 的循环。写之后立刻读，浏览器无法等到帧边界，只能当场清脏标记、同步算完布局。元素越多，强制布局次数越多，耗时呈线性增长，且每次都把后续样式计算拖下水。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>浏览器默认异步布局：一帧内多次修改先累积，帧边界统一算一次。但读取 <code>offsetWidth/getBoundingClientRect/getComputedStyle</code> 会要求“现在就要准确几何”，于是强制同步布局。修复范式是把逻辑拆成 measure 与 mutate 两段：先全读进数组，再统一写回，中间不穿插读取。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>像素酱的改造：第一遍 map 读出所有高度求最大值，第二遍 forEach 统一写 <code>minHeight</code>。再用 <code>contain:layout</code> 收窄重排边界，滚动场景用 rAF 合并高频读取。火焰图里 Layout 从“密密麻麻”变成“一帧一条”，单次按键耗时从 26ms 降到 4ms。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>几何读取 API 会强制同步布局：<code>offset*</code>、<code>client*</code>、<code>scroll*</code>、<code>getBoundingClientRect</code>。</li><li>读写交错 = layout thrashing；全读 → 全写 = 一帧一次布局。</li><li>能用 CSS 表达的布局（<code>calc</code>、flex、grid）不要交给 JS 测量。</li><li>ResizeObserver 回调里只记录尺寸，写入放下一帧，避免循环。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把读和写拆开后，为什么总耗时可能还是很高？</p><p><strong>答</strong>：拆开只减少“布局次数”，不减少总计算量。如果单次布局本身很大（元素多、层级深、复杂选择器），仍需用 <code>contain</code> 缩小边界、<code>content-visibility</code> 跳过屏外内容、减少 DOM 规模。布局性能是“次数 × 单次成本”的乘积。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>交错 vs 批量的 200 元素实测：<a href="./../../examples/mechanism/03-layout-and-forced-sync">examples/mechanism/03-layout-and-forced-sync</a></li><li>在 Performance 面板录制，搜索 Layout 事件数量对比两种写法。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>布局省了，绘制也想省。第 58 话《合成层与 GPU 加速的真实条件》——为什么你加的 <code>translateZ(0)</code> 反而更卡。</p>',22)])])}const f=a(r,[["render",i]]);export{m as __pageData,f as default};
